23	/**
24	 The {@link Safelist}-based HTML cleaner. Use to ensure that end-user provided HTML contains only the elements and attributes
25	 that you are expecting; no junk, and no cross-site scripting attacks!
26	 <p>
27	 The HTML cleaner parses the input as HTML and then runs it through a safelist, so the output HTML can only contain
28	 HTML that is allowed by the safelist.
29	 </p>
30	 <p>
31	 It is assumed that the input HTML is a body fragment; the clean methods only pull from the source's body, and the
32	 canned safelists only allow body-contained tags.
33	 </p>
34	 <p>
35	 Rather than interacting directly with a Cleaner object, generally see the {@code clean} methods in {@link org.jsoup.Jsoup}.
36	 </p>
37	 <p>
38	 A Cleaner may be reused across multiple documents and shared across concurrent threads once its {@link Safelist} has
39	 been configured. The cleaner uses the supplied safelist directly, so later safelist changes affect later cleaning
40	 calls. If you need a variant of an existing configuration, use {@link Safelist#Safelist(Safelist)} to make a copy.
41	 </p>
42	 */
43	public class Cleaner {
44	    private final Safelist safelist;
45	
46	    /**
47	     Create a new cleaner, that sanitizes documents using the supplied safelist.
48	     @param safelist safe-list to clean with
49	     */
50	    public Cleaner(Safelist safelist) {
51	        Validate.notNull(safelist);
52	        this.safelist = safelist;
53	    }
54	
55	    /**
56	     Creates a new, clean document, from the original dirty document, containing only elements allowed by the safelist.
57	     The original document is not modified. Only elements from the dirty document's <code>body</code> are used. The
58	     OutputSettings of the original document are cloned into the clean document.
59	     @param dirtyDocument Untrusted base document to clean.
60	     @return cleaned document.
61	     */
62	    public Document clean(Document dirtyDocument) {
63	        Validate.notNull(dirtyDocument);
64	
65	        Document clean = Document.createShell(dirtyDocument.baseUri());
66	        copySafeNodes(dirtyDocument.body(), clean.body());
67	        clean.outputSettings(dirtyDocument.outputSettings().clone());
68	
69	        return clean;
70	    }
71	
72	    /**
73	     Determines if the input document's <b>body</b> is valid, against the safelist. It is considered valid if all the
74	     tags and attributes in the input HTML are allowed by the safelist, and that there is no content in the
75	     <code>head</code>.
76	     <p>
77	     This method is intended to be used in a user interface as a validator for user input. Note that regardless of the
78	     output of this method, the input document <b>must always</b> be normalized using a method such as
79	     {@link #clean(Document)}, and the result of that method used to store or serialize the document before later reuse
80	     such as presentation to end users. This ensures that enforced attributes are set correctly, and that any
81	     differences between how a given browser and how jsoup parses the input HTML are normalized.
82	     </p>
83	     <p>Example:
84	     <pre>{@code
85	     Document inputDoc = Jsoup.parse(inputHtml);
86	     Cleaner cleaner = new Cleaner(Safelist.relaxed());
87	     boolean isValid = cleaner.isValid(inputDoc);
88	     Document normalizedDoc = cleaner.clean(inputDoc);
89	     }</pre>
90	     </p>
91	     @param dirtyDocument document to test
92	     @return true if no tags or attributes need to be removed; false if they do
93	     */
94	    public boolean isValid(Document dirtyDocument) {
95	        Validate.notNull(dirtyDocument);
96	
97	        Document clean = Document.createShell(dirtyDocument.baseUri());
98	        int numDiscarded = copySafeNodes(dirtyDocument.body(), clean.body());
99	        return numDiscarded == 0
100	            && dirtyDocument.head().childNodes().isEmpty(); // because we only look at the body, but we start from a shell, make sure there's nothing in the head
101	    }
102	
103	    /**
104	     Determines if the input <b>body HTML</b> is valid, against the supplied safelist. It is considered valid if all
105	     the tags and attributes in the input HTML are allowed by the safelist, and no tag, attribute, or attribute value
106	     would be removed or rewritten by the cleaner. The input is parsed as an HTML body fragment and is not modified;
107	     malformed URLs are treated as invalid, without throwing.
108	     <p>
109	     This method applies the same safety checks as {@link #clean(Document)}, so its result always reflects the current
110	     safelist configuration. It is intended to be used in a user interface as a validator for user input. Note that
111	     regardless of the output of this method, the input HTML <b>must always</b> be normalized using a method such as
112	     {@link #clean(Document)}, and the result of that method used to store or serialize the document before later
113	     reuse such as presentation to end users. This ensures that enforced attributes are set correctly, and that any
114	     differences between how a given browser and how jsoup parses the input HTML are normalized.
115	     </p>
116	     <p>Example:
117	     <pre>{@code
118	     Safelist safelist = Safelist.relaxed();
119	     boolean isValid = Cleaner.isValid(inputHtml, safelist);
120	     String normalizedHtml = Jsoup.clean(inputHtml, "https://example.com/", safelist);
121	     }</pre>
122	     </p>
123	     @param bodyHtml HTML fragment to test
124	     @param safelist safelist to test against
125	     @return true if no tags or attributes need to be removed; false if they do
126	     */
127	    public static boolean isValid(String bodyHtml, Safelist safelist) {
128	        return new Cleaner(safelist).isValidBodyHtml(bodyHtml);
129	    }
130	
131	    /**
132	     Determines if the input document's <b>body HTML</b> is valid, against the safelist. It is considered valid if all
133	     the tags and attributes in the input HTML are allowed by the safelist.
134	     <p>
135	     This method is intended to be used in a user interface as a validator for user input. Note that regardless of the
136	     output of this method, the input document <b>must always</b> be normalized using a method such as
137	     {@link #clean(Document)}, and the result of that method used to store or serialize the document before later reuse
138	     such as presentation to end users. This ensures that enforced attributes are set correctly, and that any
139	     differences between how a given browser and how jsoup parses the input HTML are normalized.
140	     </p>
141	     <p>Example:
142	     <pre>{@code
143	     Document inputDoc = Jsoup.parse(inputHtml);
144	     Cleaner cleaner = new Cleaner(Safelist.relaxed());
145	     boolean isValid = cleaner.isValidBodyHtml(inputHtml);
146	     Document normalizedDoc = cleaner.clean(inputDoc);
147	     }</pre>
148	     </p>
149	     @param bodyHtml HTML fragment to test
150	     @return true if no tags or attributes need to be removed; false if they do
151	     */
152	    public boolean isValidBodyHtml(String bodyHtml) {
153	        String baseUri = (safelist.preserveRelativeLinks()) ? DummyUri : ""; // fake base URI to allow relative URLs to remain valid
154	        Document clean = Document.createShell(baseUri);
155	        Document dirty = Document.createShell(baseUri);
156	        ParseErrorList errorList = ParseErrorList.tracking(1);
157	        List<Node> nodes = Parser.parseFragment(bodyHtml, dirty.body(), baseUri, errorList);
158	        dirty.body().insertChildren(0, nodes);
159	        int numDiscarded = copySafeNodes(dirty.body(), clean.body());
160	        return numDiscarded == 0 && errorList.isEmpty();
161	    }
162	
163	    /**
164	     Iterates the input and copies trusted nodes (tags, attributes, text) into the destination.
165	     */
166	    private final class CleaningVisitor implements NodeVisitor {
167	        private int numDiscarded = 0;
168	        private final Element root;
169	        private Element destination; // current element to append nodes to
170	
171	        private CleaningVisitor(Element root, Element destination) {
172	            this.root = root;
173	            this.destination = destination;
174	        }
175	
176	        @Override public void head(Node source, int depth) {
177	            if (source instanceof Element) {
178	                Element sourceEl = (Element) source;
179	
180	                if (safelist.isSafeTag(sourceEl.normalName())) { // safe, clone and copy safe attrs
181	                    ElementMeta meta = createSafeElement(sourceEl);
182	                    Element destChild = meta.el;
183	                    destination.appendChild(destChild);
184	
185	                    numDiscarded += meta.numAttribsDiscarded;
186	                    destination = destChild;
187	                } else if (source != root) { // not a safe tag, so don't add. don't count root against discarded.
188	                    numDiscarded++;
189	                }
190	            } else if (source instanceof TextNode) {
191	                TextNode sourceText = (TextNode) source;
192	                TextNode destText = new TextNode(sourceText.getWholeText());
193	                destination.appendChild(destText);
194	            } else if (source instanceof DataNode && safelist.isSafeTag(source.parent().normalName())) {
195	                DataNode sourceData = (DataNode) source;
196	                DataNode destData = new DataNode(sourceData.getWholeData());
197	                destination.appendChild(destData);
198	            } else { // else, we don't care about comments, xml proc instructions, etc
199	                numDiscarded++;
200	            }
201	        }
202	
203	        @Override public void tail(Node source, int depth) {
204	            if (source instanceof Element && safelist.isSafeTag(source.normalName())) {
205	                destination = destination.parent(); // would have descended, so pop destination stack
206	            }
207	        }
208	    }
209	
210	    private int copySafeNodes(Element source, Element dest) {
211	        CleaningVisitor cleaningVisitor = new CleaningVisitor(source, dest);
212	        cleaningVisitor.traverse(source);
213	        return cleaningVisitor.numDiscarded;
214	    }
215	
216	    private ElementMeta createSafeElement(Element sourceEl) {
217	        Element dest = sourceEl.shallowClone(); // reuses tag, clones attributes and preserves any user data
218	        String sourceTag = sourceEl.tagName();
219	        Attributes destAttrs = dest.attributes();
220	        dest.clearAttributes(); // clear all non-internal attributes, ready for safe copy
221	
222	        int numDiscarded = 0;
223	        Attributes sourceAttrs = sourceEl.attributes();
224	        for (Attribute sourceAttr : sourceAttrs) {
225	            if (safelist.isSafeAttribute(sourceTag, sourceEl, sourceAttr)) { // will keep this attr
226	                String key = sourceAttr.getKey();
227	                String value = sourceAttr.getValue();
228	
229	                if (Safelist.isSrcset(key)) { // clean the srcset candidates; drop the attribute if none survive
230	                    String cleaned = safelist.cleanSrcset(sourceTag, sourceEl, value);
231	                    if (cleaned == null) {
232	                        numDiscarded++;
233	                        continue;
234	                    }
235	                    if (!cleaned.equals(value))
236	                        numDiscarded++; // candidates were dropped or normalized
237	                    value = cleaned;
238	                } else if (safelist.shouldAbsUrl(sourceTag, key)) { // configured to make absolute urls for this key (href)
239	                    value = sourceEl.absUrl(key);
240	                    if (value.isEmpty()) // could not be made abs; leave as-is to allow custom unknown protocols
241	                        value = sourceAttr.getValue();
242	                }
243	                Range.AttributeRange range = sourceAttrs.sourceRange(key);
244	                destAttrs.put(key, value);
245	                NodeInternals.attributeRange(destAttrs, key, range);
246	            } else
247	                numDiscarded++;
248	        }
249	
250	        Attributes enforcedAttrs = safelist.getEnforcedAttributes(sourceTag);
251	        // special case for <a href rel=nofollow>, only apply to external links:
252	        if (sourceEl.nameIs("a") && enforcedAttrs.get("rel").equals("nofollow")) {
253	            String href = sourceEl.absUrl("href");
254	            if (!href.isEmpty()) {
255	                try {
256	                    URL baseUrl = new URL(sourceEl.baseUri());
257	                    URL linkUrl = new URL(href);
258	                    String baseHost = baseUrl.getHost();
259	                    if (!baseHost.isEmpty() && baseHost.equalsIgnoreCase(linkUrl.getHost())) // same site, so don't set the nofollow
260	                        enforcedAttrs.remove("rel");
261	                } catch (MalformedURLException ignored) {}
262	            }
263	        }
264	
265	        // apply enforced attributes case-insensitively, so a preserved-case source attr is canonicalized to the enforced key
266	        for (Attribute enforcedAttr : enforcedAttrs) {
267	            destAttrs.removeIgnoreCase(enforcedAttr.getKey());
268	            destAttrs.put(enforcedAttr.getKey(), enforcedAttr.getValue());
269	        }
270	        dest.attributes().addAll(destAttrs); // re-attach, if removed in clear
271	        return new ElementMeta(dest, numDiscarded);
272	    }
273	
274	    private static class ElementMeta {
275	        Element el;
276	        int numAttribsDiscarded;
277	
278	        ElementMeta(Element el, int numAttribsDiscarded) {
279	            this.el = el;
280	            this.numAttribsDiscarded = numAttribsDiscarded;
281	        }
282	    }
