251	    /**
252	     Add a list of allowed elements to a safelist. (If a tag is not allowed, it will be removed from the HTML.)
253	
254	     @param tags tag names to allow
255	     @return this (for chaining)
256	     */
257	    public Safelist addTags(String... tags) {
258	        Validate.notNull(tags);
259	
260	        for (String tagName : tags) {
261	            Validate.notEmpty(tagName);
262	            Validate.isFalse(tagName.equalsIgnoreCase("noscript"),
263	                "noscript is unsupported in Safelists, due to incompatibilities between parsers with and without script-mode enabled");
264	            tagNames.add(TagName.valueOf(tagName));
265	        }
266	        return this;
267	    }
268	
269	    /**
270	     Remove a list of allowed elements from a safelist. (If a tag is not allowed, it will be removed from the HTML.)
271	
272	     @param tags tag names to disallow
273	     @return this (for chaining)
274	     */
275	    public Safelist removeTags(String... tags) {
276	        Validate.notNull(tags);
277	
278	        for(String tag: tags) {
279	            Validate.notEmpty(tag);
280	            TagName tagName = TagName.valueOf(tag);
281	
282	            if(tagNames.remove(tagName)) { // Only look in sub-maps if tag was allowed
283	                attributes.remove(tagName);
284	                enforcedAttributes.remove(tagName);
285	                protocols.remove(tagName);
286	            }
287	        }
288	        return this;
289	    }
