369	    /**
370	     Add an enforced attribute to a tag. An enforced attribute will always be added to the element. If the element
371	     already has the attribute set, it will be overridden with this value.
372	     <p>
373	     E.g.: <code>addEnforcedAttribute("a", "rel", "nofollow")</code> will make all <code>a</code> tags output as
374	     <code>&lt;a href="..." rel="nofollow"&gt;</code>
375	     </p>
376	
377	     @param tag   The tag the enforced attribute is for. The tag will be added to the allowed tag list if necessary.
378	     @param attribute   The attribute name
379	     @param value The enforced attribute value
380	     @return this (for chaining)
381	     */
382	    public Safelist addEnforcedAttribute(String tag, String attribute, String value) {
383	        Validate.notEmpty(tag);
384	        Validate.notEmpty(attribute);
385	        Validate.notEmpty(value);
386	
387	        TagName tagName = TagName.valueOf(tag);
388	        tagNames.add(tagName);
389	        AttributeKey attrKey = AttributeKey.valueOf(attribute);
390	        AttributeValue attrVal = AttributeValue.valueOf(value);
391	
392	        Map<AttributeKey, AttributeValue> attrMap = enforcedAttributes.computeIfAbsent(tagName, k -> new HashMap<>());
393	        attrMap.put(attrKey, attrVal);
394	        return this;
395	    }
396	
397	    /**
398	     Remove a previously configured enforced attribute from a tag.
399	
400	     @param tag   The tag the enforced attribute is for.
401	     @param attribute   The attribute name
402	     @return this (for chaining)
403	     */
404	    public Safelist removeEnforcedAttribute(String tag, String attribute) {
405	        Validate.notEmpty(tag);
406	        Validate.notEmpty(attribute);
407	
408	        TagName tagName = TagName.valueOf(tag);
409	        if(tagNames.contains(tagName) && enforcedAttributes.containsKey(tagName)) {
410	            AttributeKey attrKey = AttributeKey.valueOf(attribute);
411	            Map<AttributeKey, AttributeValue> attrMap = enforcedAttributes.get(tagName);
412	            attrMap.remove(attrKey);
413	
414	            if(attrMap.isEmpty()) // Remove tag from enforced attribute map if no enforced attributes are present
415	                enforcedAttributes.remove(tagName);
416	        }
417	        return this;
418	    }
