516	    /**
517	     * Test if the supplied tag is allowed by this safelist.
518	     * @param tag test tag
519	     * @return true if allowed
520	     */
521	    public boolean isSafeTag(String tag) {
522	        return tagNames.contains(TagName.valueOf(tag));
523	    }
524	
525	    /**
526	     * Test if the supplied attribute is allowed by this safelist for this tag.
527	     * <p>This method does not modify the input element or attribute.</p>
528	     * <p>Note that for {@code srcset} attributes, which hold a comma-separated list of URL candidates, this method
529	     * only tests that the attribute itself is allowed; the {@link Cleaner} validates each candidate URL against the
530	     * configured protocols when cleaning.</p>
531	     * @param tagName tag to consider allowing the attribute in
532	     * @param el element under test, to confirm protocol
533	     * @param attr attribute under test
534	     * @return true if allowed
535	     */
536	    public boolean isSafeAttribute(String tagName, Element el, Attribute attr) {
537	        TagName tag = TagName.valueOf(tagName);
538	        AttributeKey key = AttributeKey.valueOf(attr.getKey());
539	
540	        Set<AttributeKey> okSet = attributes.get(tag);
541	        if (okSet != null && okSet.contains(key)) {
542	            if (protocols.containsKey(tag)) {
543	                Map<AttributeKey, Set<Protocol>> attrProts = protocols.get(tag);
544	                // ok if not defined protocol; otherwise test. srcset URLs are tested per candidate in the Cleaner.
545	                return !attrProts.containsKey(key) || isSrcset(attr.getKey())
546	                    || (isSoundUrlValue(attr.getValue())
547	                        && isSafeProtocol(getProtocolValue(el, attr), attrProts.get(key)));
548	            } else { // attribute found, no protocols defined, so OK
549	                return true;
550	            }
551	        }
552	        Map<AttributeKey, AttributeValue> enforcedSet = enforcedAttributes.get(tag);
553	        if (enforcedSet != null && enforcedSet.containsKey(key)) {
554	            // enforced attr key was LCed via AttributeKey.valueOf(attr.getKey()),
555	            // if the input already has that exact value, treat it as safe
556	            return enforcedSet.get(key).equals(AttributeValue.valueOf(attr.getValue()));
557	        }
558	        // no attributes defined for tag, try :all tag
559	        return !tagName.equals(All) && isSafeAttribute(All, el, attr);
560	    }
561	
562	    private String getProtocolValue(Element el, Attribute attr) {
563	        String value = el.absUrl(attr.getKey());
564	        if (value.isEmpty() && !StringUtil.hasHttpScheme(attr.getValue()))
565	            value = attr.getValue(); // if it could not be made abs, run as-is to allow custom unknown protocols
566	        return value;
567	    }
568	
569	    private static final Pattern BareScheme = Pattern.compile("^[a-zA-Z][a-zA-Z0-9+-.]*:$");
570	
571	    /**
572	     Tests if a single-value URL attribute value is structurally sound for protocol validation. Empty and
573	     whitespace-only values are left to the standard resolution rules. Otherwise, the value must not contain control
574	     characters or whitespace, and must not be a bare scheme (e.g. {@code "mailto:"}) with no content after the
575	     colon.
576	     */
577	    private static boolean isSoundUrlValue(String value) {
578	        if (StringUtil.isBlank(value)) return true; // blank values follow the standard resolution rules
579	        for (int i = 0, length = value.length(); i < length; i++) {
580	            char c = value.charAt(i);
581	            if (c <= 0x20 || c == 0x7f) return false; // control character or whitespace within the URL
582	        }
583	        return !BareScheme.matcher(value).matches();
584	    }
585	
586	    private boolean isSafeProtocol(String value, Set<Protocol> protocols) {
587	        for (Protocol protocol : protocols) {
588	            String prot = protocol.toString();
589	
590	            if (prot.equals("#")) { // allows anchor links
591	                if (isValidAnchor(value)) {
592	                    return true;
593	                } else {
594	                    continue;
595	                }
596	            }
597	
598	            String lc = lowerCase(value);
599	            if (lc.startsWith(prot)
600	                && lc.length() > prot.length()
601	                && lc.charAt(prot.length()) == ':') {
602	                return true;
603	            }
604	        }
605	        return false;
606	    }
607	
608	    /**
609	     Tests if the attribute is {@code srcset} (case-insensitive), which holds a comma-separated list of image
610	     candidate URLs and so gets per-candidate cleaning in the {@link Cleaner}.
611	     */
612	    static boolean isSrcset(String attrKey) {
613	        return attrKey.equalsIgnoreCase(Srcset);
614	    }
615	
616	    /**
617	     Cleans a {@code srcset} attribute value, candidate by candidate. Candidates with invalid syntax (missing URL,
618	     empty candidates, malformed descriptors, or trailing junk) are dropped, as are those whose URL fails the
619	     protocol checks configured for the attribute on this tag. Surviving candidates keep their original order and
620	     are normalized to {@code url descriptor, url descriptor} form. Does not throw on malformed input.
621	
622	     @param tagName the tag the attribute is on; selects the applicable protocol configuration
623	     @param el the element the attribute is on, to resolve URLs against its base URI
624	     @param value the source srcset attribute value
625	     @return the cleaned value, or {@code null} if no candidates survive (in which case the attribute is removed)
626	     */
627	    String cleanSrcset(String tagName, Element el, String value) {
628	        Set<Protocol> protocols = srcsetProtocols(TagName.valueOf(tagName));
629	        StringBuilder sb = StringUtil.borrowBuilder();
630	
631	        int pos = 0, length = value.length();
632	        while (pos <= length) {
633	            // find the end of this candidate: a comma separates candidates, unless it is within the URL and directly
634	            // followed by a non-whitespace, non-comma character (e.g. the comma in a data: URL). Consecutive
635	            // separators produce empty candidates, which are invalid.
636	            int start = pos, end = pos;
637	            boolean inUrl = true; // still scanning the URL run (no whitespace after URL content yet)
638	            boolean started = false; // seen non-whitespace content in this candidate
639	            while (end < length) {
640	                char c = value.charAt(end);
641	                if (c == ',') {
642	                    if (inUrl && started && end + 1 < length && !isSrcsetSpace(value.charAt(end + 1)) && value.charAt(end + 1) != ',')
643	                        end++; // comma is part of the URL
644	                    else
645	                        break; // candidate separator
646	                } else {
647	                    if (isSrcsetSpace(c)) {
648	                        if (started) inUrl = false;
649	                    } else {
650	                        started = true;
651	                    }
652	                    end++;
653	                }
654	            }
655	            appendSrcsetCandidate(el, value, start, end, protocols, sb);
656	            if (end >= length) break;
657	            pos = end + 1; // step past the separator comma
658	        }
659	
660	        if (sb.length() == 0) {
661	            StringUtil.releaseBuilderVoid(sb);
662	            return null;
663	        }
664	        return StringUtil.releaseBuilder(sb);
665	    }
666	
667	    /**
668	     Validates and appends a single srcset candidate (the {@code value} range {@code start}..{@code end}) to
669	     {@code sb}. Invalid or unsafe candidates are silently dropped; their text is never recombined into new URLs.
670	     */
671	    private void appendSrcsetCandidate(Element el, String value, int start, int end, Set<Protocol> protocols, StringBuilder sb) {
672	        // trim ASCII whitespace from the candidate
673	        while (start < end && isSrcsetSpace(value.charAt(start))) start++;
674	        while (end > start && isSrcsetSpace(value.charAt(end - 1))) end--;
675	        if (start == end) return; // empty candidate (e.g. from consecutive separators)
676	
677	        // the URL is the leading run of non-whitespace
678	        int urlEnd = start;
679	        while (urlEnd < end && !isSrcsetSpace(value.charAt(urlEnd))) urlEnd++;
680	        String url = value.substring(start, urlEnd);
681	
682	        // an optional descriptor may follow, introduced by at least one ASCII space
683	        String descriptor = null;
684	        if (urlEnd < end) {
685	            if (value.charAt(urlEnd) != ' ') return; // the descriptor must be space-separated from the URL
686	            int descStart = urlEnd;
687	            while (descStart < end && value.charAt(descStart) == ' ') descStart++;
688	            int descEnd = descStart;
689	            while (descEnd < end && !isSrcsetSpace(value.charAt(descEnd))) descEnd++;
690	            if (descEnd != end) return; // unexpected content after the descriptor (e.g. a second descriptor)
691	            descriptor = value.substring(descStart, descEnd);
692	            if (!isValidSrcsetDescriptor(descriptor)) return;
693	        }
694	
695	        if (protocols != null && !isSafeSrcsetUrl(el, url, protocols)) return;
696	
697	        if (sb.length() > 0) sb.append(", ");
698	        sb.append(url);
699	        if (descriptor != null) sb.append(' ').append(descriptor);
700	    }
701	
702	    /**
703	     Finds the protocol configuration applicable to {@code srcset} on the given tag, following the same tag to
704	     {@code :all} fallback as {@link #isSafeAttribute}, so that per-tag differences neither widen nor narrow each
705	     other. Returns {@code null} when URLs are unrestricted.
706	     */
707	    private Set<Protocol> srcsetProtocols(TagName tag) {
708	        Set<AttributeKey> okSet = attributes.get(tag);
709	        if (okSet != null && okSet.contains(SrcsetKey)) {
710	            Map<AttributeKey, Set<Protocol>> attrProts = protocols.get(tag);
711	            return attrProts != null ? attrProts.get(SrcsetKey) : null;
712	        }
713	        Map<AttributeKey, AttributeValue> enforcedSet = enforcedAttributes.get(tag);
714	        if (enforcedSet != null && enforcedSet.containsKey(SrcsetKey)) return null;
715	        return !tag.equals(AllTag) ? srcsetProtocols(AllTag) : null;
716	    }
717	
718	    private boolean isSafeSrcsetUrl(Element el, String url, Set<Protocol> protocols) {
719	        // apply the same structural rules as for a single-value URL attribute: no control characters or inner
720	        // whitespace, and no bare scheme (e.g. "javascript:") with nothing after the colon
721	        if (!isSoundUrlValue(url)) return false;
722	        // the scheme must still be allowed after percent-decoding and stripping control characters, so that a
723	        // dangerous scheme cannot hide behind e.g. "java%73cript:", "%6Aavascript:", "%00javascript:", or leading
724	        // whitespace and control bytes
725	        if (!isSafeDecodedScheme(url, protocols)) return false;
726	
727	        String value = StringUtil.resolve(el.baseUri(), url);
728	        if (value.isEmpty() && !StringUtil.hasHttpScheme(url))
729	            value = url; // if it could not be made absolute, run as-is to allow custom unknown protocols
730	        return isSafeProtocol(value, protocols);
731	    }
732	
733	    /**
734	     Checks the scheme of a candidate URL against the configured protocols, after undoing obfuscations that could hide
735	     a dangerous scheme from a naive prefix check. A real URL scheme is terminated by a <b>literal</b> colon, so the
736	     raw value is scanned for its first colon; percent-encoded bytes and ASCII control characters in the scheme run
737	     before that colon are normalized (e.g. {@code java%73cript:}, {@code %6Aavascript:}, and {@code java%00script:}
738	     all reveal {@code javascript:}). A value with no literal-colon scheme (a relative reference such as
739	     {@code x%3Ay.jpg} or an already-encoded {@code http%3a//host}) is left to the standard base-URI resolution
740	     rules, exactly like a single-value URL attribute. Never throws.
741	     */
742	    private static boolean isSafeDecodedScheme(String url, Set<Protocol> protocols) {
743	        int colon = url.indexOf(':');
744	        if (colon <= 0) return true; // no literal scheme separator: a relative / protocol-relative reference
745	
746	        String head = url.substring(0, colon);
747	        // the scheme run may only contain scheme characters or percent-escapes; anything else (e.g. a leading "//")
748	        // means this colon is not a scheme separator
749	        int length = head.length();
750	        boolean sawEscape = false;
751	        for (int i = 0; i < length; i++) {
752	            char c = head.charAt(i);
753	            if (c == '%') { sawEscape = true; continue; }
754	            boolean schemeChar = (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z')
755	                || (c >= '0' && c <= '9') || c == '+' || c == '-' || c == '.';
756	            if (!schemeChar) return true; // not a scheme; defer to base-URI resolution
757	        }
758	        if (!sawEscape) return true; // an unescaped scheme is checked by the normal resolved-URL protocol test
759	
760	        // decode the escaped bytes and drop any revealed control characters, then confirm a well-formed scheme
761	        String decoded = stripControlChars(percentDecode(head));
762	        if (decoded.isEmpty() || !isSchemeAlpha(decoded.charAt(0))) return true;
763	        for (int i = 0; i < decoded.length(); i++) {
764	            char c = decoded.charAt(i);
765	            boolean schemeChar = (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z')
766	                || (c >= '0' && c <= '9') || c == '+' || c == '-' || c == '.';
767	            if (!schemeChar) return true; // decoding revealed a non-scheme byte, so it is a relative reference
768	        }
769	
770	        String scheme = lowerCase(decoded);
771	        for (Protocol protocol : protocols) {
772	            String prot = protocol.toString();
773	            if (!prot.equals("#") && scheme.equals(prot)) return true; // the "#" pseudo-protocol never matches a scheme
774	        }
775	        return false;
776	    }
777	
778	    /** Removes ASCII control characters (0x00-0x1F and DEL), which browsers ignore when reading a URL scheme. */
779	    private static String stripControlChars(String value) {
780	        int length = value.length();
781	        StringBuilder stripped = null;
782	        for (int i = 0; i < length; i++) {
783	            char c = value.charAt(i);
784	            if (c <= 0x1f || c == 0x7f) {
785	                if (stripped == null) {
786	                    stripped = new StringBuilder(length);
787	                    stripped.append(value, 0, i);
788	                }
789	            } else if (stripped != null) {
790	                stripped.append(c);
791	            }
792	        }
793	        return stripped != null ? stripped.toString() : value;
794	    }
795	
796	    /**
797	     Leniently decodes {@code %XX} percent-escapes to their (ISO-8859-1 mapped) character. Malformed or incomplete
798	     escapes are left as-is. Used only to reveal an obfuscated URL scheme, so decoding never throws and charset
799	     subtleties outside the ASCII scheme are irrelevant.
800	     */
801	    private static String percentDecode(String url) {
802	        int length = url.length();
803	        if (length < 3 || url.indexOf('%') == -1) return url;
804	        StringBuilder decoded = null;
805	        for (int i = 0; i < length; i++) {
806	            char c = url.charAt(i);
807	            if (c == '%' && i + 2 < length) {
808	                int hi = Character.digit(url.charAt(i + 1), 16);
809	                int lo = Character.digit(url.charAt(i + 2), 16);
810	                if (hi >= 0 && lo >= 0) {
811	                    if (decoded == null) {
812	                        decoded = new StringBuilder(length);
813	                        decoded.append(url, 0, i);
814	                    }
815	                    decoded.append((char) ((hi << 4) | lo));
816	                    i += 2;
817	                    continue;
818	                }
819	            }
820	            if (decoded != null) decoded.append(c);
821	        }
822	        return decoded != null ? decoded.toString() : url;
823	    }
824	
825	    /**
826	     Validates a srcset descriptor: a positive integer followed by a lowercase {@code w} (e.g. {@code 100w}), or a
827	     positive number (digits, or digits.digits) followed by a lowercase {@code x} (e.g. {@code 2x}, {@code 1.5x}).
828	     Signs, exponents, a dot missing a side, and zero values are all invalid.
829	     */
830	    private static boolean isValidSrcsetDescriptor(String descriptor) {
831	        int length = descriptor.length();
832	        if (length < 2) return false;
833	        String number = descriptor.substring(0, length - 1);
834	        switch (descriptor.charAt(length - 1)) {
835	            case 'w': return isPositiveInteger(number);
836	            case 'x': return isPositiveNumber(number);
837	            default:  return false;
838	        }
839	    }
840	
841	    /** Tests if the value is all digits and greater than zero. */
842	    private static boolean isPositiveInteger(String number) {
843	        boolean nonZero = false;
844	        for (int i = 0, length = number.length(); i < length; i++) {
845	            char c = number.charAt(i);
846	            if (c < '0' || c > '9') return false;
847	            if (c != '0') nonZero = true;
848	        }
849	        return nonZero;
850	    }
851	
852	    /** Tests if the value is digits, or digits.digits, and greater than zero. */
853	    private static boolean isPositiveNumber(String number) {
854	        int dot = number.indexOf('.');
855	        if (dot == -1) return isPositiveInteger(number);
856	        if (number.indexOf('.', dot + 1) != -1) return false; // at most one dot
857	        String integer = number.substring(0, dot);
858	        String fraction = number.substring(dot + 1);
859	        if (!isDigits(integer) || !isDigits(fraction)) return false; // the dot needs digits on both sides
860	        return isPositiveInteger(integer) || isPositiveInteger(fraction);
861	    }
862	
863	    private static boolean isDigits(String value) {
864	        for (int i = 0, length = value.length(); i < length; i++) {
865	            char c = value.charAt(i);
866	            if (c < '0' || c > '9') return false;
867	        }
868	        return value.length() > 0;
869	    }
870	
871	    /** The ASCII whitespace characters: space, tab, newline, carriage return, and form feed. */
872	    private static boolean isSrcsetSpace(char c) {
873	        return c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\f';
874	    }
875	
876	    /** Tests if the character is an ASCII letter, the required first character of a URL scheme. */
877	    private static boolean isSchemeAlpha(char c) {
878	        return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z');
879	    }
880	
881	    /**
882	     Check if a URL attribute should be normalized to an absolute URL in the cleaned output. Uses the configured
883	     protocols for that tag+attribute pair, falling back to {@code :all} only if the tag does not define the
884	     attribute.
885	     */
886	    boolean shouldAbsUrl(String tagName, String attrKey) {
887	        if (preserveRelativeLinks) return false;
888	        return shouldAbsUrl(TagName.valueOf(tagName), AttributeKey.valueOf(attrKey));
889	    }
890	
891	    private boolean shouldAbsUrl(TagName tag, AttributeKey key) {
892	        Set<AttributeKey> allowedAttrs = attributes.get(tag);
893	        if (allowedAttrs != null && allowedAttrs.contains(key)) {
894	            Map<AttributeKey, Set<Protocol>> protocolsByAttr = protocols.get(tag);
895	            return protocolsByAttr != null && protocolsByAttr.containsKey(key);
896	        }
897	
898	        Map<AttributeKey, AttributeValue> enforcedAttrs = enforcedAttributes.get(tag);
899	        if (enforcedAttrs != null && enforcedAttrs.containsKey(key)) return false;
900	
901	        return !tag.equals(AllTag) && shouldAbsUrl(AllTag, key);
902	    }
903	
904	    private static boolean isValidAnchor(String value) {
905	        return value.startsWith("#") && !value.matches(".*\\s.*");
906	    }
907	
908	    /**
909	     Gets the Attributes that should be enforced for a given tag
910	     * @param tagName the tag
911	     * @return the attributes that will be enforced; empty if none are set for the given tag
912	     */
913	    public Attributes getEnforcedAttributes(String tagName) {
914	        Attributes attrs = new Attributes();
915	        TagName tag = TagName.valueOf(tagName);
916	        if (enforcedAttributes.containsKey(tag)) {
917	            Map<AttributeKey, AttributeValue> keyVals = enforcedAttributes.get(tag);
918	            for (Map.Entry<AttributeKey, AttributeValue> entry : keyVals.entrySet()) {
919	                attrs.put(entry.getKey().toString(), entry.getValue().toString());
920	            }
921	        }
922	        return attrs;
923	    }
924	    
925	    // named types for config. All just hold strings, but here for my sanity.
926	
927	    static class TagName extends TypedValue {
928	        TagName(String value) {
929	            super(value);
930	        }
931	
932	        static TagName valueOf(String value) {
933	            return new TagName(Normalizer.lowerCase(value));
934	        }
935	    }
936	
937	    static class AttributeKey extends TypedValue {
938	        AttributeKey(String value) {
939	            super(value);
940	        }
941	
942	        static AttributeKey valueOf(String value) {
943	            return new AttributeKey(Normalizer.lowerCase(value));
944	        }
945	    }
946	
947	    static class AttributeValue extends TypedValue {
948	        AttributeValue(String value) {
949	            super(value);
950	        }
951	
952	        static AttributeValue valueOf(String value) {
953	            return new AttributeValue(value);
954	        }
955	    }
956	
957	    static class Protocol extends TypedValue {
958	        Protocol(String value) {
959	            super(value);
960	        }
961	
962	        static Protocol valueOf(String value) {
963	            return new Protocol(value);
964	        }
965	    }
966	
967	    abstract static class TypedValue {
968	        private final String value;
969	
970	        TypedValue(String value) {
971	            Validate.notNull(value);
972	            this.value = value;
973	        }
974	
975	        @Override
976	        public int hashCode() {
977	            return value.hashCode();
978	        }
979	
980	        @Override
981	        public boolean equals(Object obj) {
982	            if (this == obj) return true;
983	            if (obj == null || getClass() != obj.getClass()) return false;
984	            TypedValue other = (TypedValue) obj;
985	            return Objects.equals(value, other.value);
986	        }
987	
988	        @Override
989	        public String toString() {
990	            return value;
991	        }
992	    }
993	}
