package org.jsoup.safety;

import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

class SrcsetFuzzTest {
    static Safelist sl() {
        return Safelist.basicWithImages()
            .addAttributes("img", "srcset")
            .addProtocols("img", "srcset", "http", "https");
    }

    static Safelist slRel() {
        return sl().preserveRelativeLinks(true);
    }

    @Test void fuzz() {
        String[] atoms = {"", ",", " ", "\t", "\n", "\f", "\r", "  ", ",,", "a.jpg", "https://ok.com/x",
            "http://ok.com/x", "1x", "2x", "100w", "0w", "0x", "1.5x", ".5x", "1.x", "-1x", "+1x",
            "javascript:alert(1)", "java%73cript:x", "data:,aaaa", "data:image/png;base64,AAAA",
            "\u0000", "\u0001", "\u007f", "//cdn.x/a", "/abs", "rel/x", "#", "?", "a,b", "a, b",
            "&#x73;", "&colon;", "java&#x73;cript:1", "java&#x73cript:1", "x%3Ay.jpg",
            "HTTP://X/Y", "custom:thing", "   ", "1x 2x", "a.jpg 0w", "\t1x", "a.jpg\t1x"};
        Safelist[] sls = {sl(), slRel()};
        String[] bases = {"https://example.com/page/", "ftp://example.com/page/", "", "https://example.com"};
        java.util.Random rnd = new java.util.Random(42);
        for (Safelist safelist : sls) {
            Cleaner cleaner = new Cleaner(safelist);
            for (String base : bases) {
                for (int i = 0; i < 20000; i++) {
                    StringBuilder sb = new StringBuilder();
                    int n = rnd.nextInt(5);
                    for (int j = 0; j < n; j++) sb.append(atoms[rnd.nextInt(atoms.length)]);
                    String val = sb.toString();
                    String html = "<img srcset='" + val.replace("'", "") + "'>";
                    Document doc;
                    try {
                        doc = Jsoup.parse(html, base);
                    } catch (Exception e) { continue; }
                    Document clean = cleaner.clean(doc);
                    assertNotNull(clean);
                    String out = clean.body().html();
                    // no dangling double commas or leading comma-space
                    if (out.contains("srcset")) {
                        String v = out.substring(out.indexOf("srcset=\"") + 8);
                        v = v.substring(0, v.indexOf('"'));
                        assertTrue(!v.contains(",,"), "double comma: " + v + " from " + val);
                        assertTrue(!v.startsWith(","), "leading comma: " + v);
                        assertTrue(!v.endsWith(","), "trailing comma: " + v);
                        assertTrue(!v.contains(", ,"), "empty middle: " + v);
                        // rejected schemes never leak
                        assertTrue(!v.toLowerCase().contains("javascript"), "leak: " + v + " from " + val);
                    }
                    // idempotency
                    Document again = cleaner.clean(clean);
                    org.junit.jupiter.api.Assertions.assertEquals(clean.body().html(), again.body().html(),
                        "not idempotent: " + val);
                }
            }
        }
    }
}

