import org.junit.jupiter.api.Test;

import java.util.regex.Matcher;
import java.util.regex.Pattern;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

class SrcsetFuzzTest {
    static Safelist sl() {
        return Safelist.basicWithImages()
            .addAttributes("img", "srcset")
            .addProtocols("img", "srcset", "http", "https");
    }

    static Safelist slAny() {
        return Safelist.basicWithImages().addAttributes("img", "srcset");
    }

    static final Pattern Scheme = Pattern.compile("^([a-zA-Z][a-zA-Z0-9+-.]*):");

    static void assertWellFormed(String value) {
        assertTrue(!value.startsWith(","), "leading comma: " + value);
        assertTrue(!value.endsWith(","), "trailing comma: " + value);
        assertTrue(!value.contains(",,"), "double comma: " + value);
        String[] cands = value.split(",", -1);
        for (String raw : cands) {
            String c = raw.trim();
            assertTrue(!c.isEmpty(), "empty candidate in: " + value);
            String[] parts = c.split("\\s+", -1);
            assertTrue(parts.length <= 2, "too many tokens: '" + c + "' in " + value);
            String url = parts[0];
            // any actual scheme must be http/https
            Matcher m = Scheme.matcher(url);
            if (m.find()) {
                String s = m.group(1).toLowerCase();
                assertTrue(s.equals("http") || s.equals("https"), "bad scheme leak: '" + url + "' in " + value);
            }
            if (parts.length == 2) {
                String d = parts[1];
                char last = d.charAt(d.length() - 1);
                assertTrue(last == 'w' || last == 'x', "bad descriptor suffix: '" + d + "' in " + value);
                String num = d.substring(0, d.length() - 1);
                assertTrue(num.matches("\\d+(\\.\\d+)?") && !num.matches("0+(\\.0+)?"),
                    "bad descriptor number: '" + d + "' in " + value);
                if (last == 'w') assertTrue(!num.contains("."), "width must be integer: " + d);
            }
        }
    }

