            "vbscript:msgbox(1)", "%6a%73:1", "1javascript:x", "a%20b.jpg"};
        Safelist[] sls = {sl(), sl().preserveRelativeLinks(true), slAny(), slAny().preserveRelativeLinks(true)};
        String[] bases = {"https://example.com/page/", "ftp://example.com/page/", "", "https://example.com",
            "http://example.com/a/b"};
        java.util.Random rnd = new java.util.Random(42);
        for (Safelist safelist : sls) {
            Cleaner cleaner = new Cleaner(safelist);
            for (String base : bases) {
                for (int i = 0; i < 30000; i++) {
                    StringBuilder sb = new StringBuilder();
                    int n = rnd.nextInt(6);
                    for (int j = 0; j < n; j++) sb.append(atoms[rnd.nextInt(atoms.length)]);
                    String val = sb.toString().replace("'", "");
