package org.jsoup.safety;

import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.junit.jupiter.api.Test;

import java.util.regex.Matcher;
import java.util.regex.Pattern;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

class SrcsetFuzzTest {
    static Safelist sl() {
        return Safelist.basicWithImages()
            .addAttributes("img", "srcset")
            .addProtocols("img", "srcset", "http", "https");
    }

    static Safelist slAny() {
        return Safelist.basicWithImages().addAttributes("img", "srcset");
    }

    static final Pattern Scheme = Pattern.compile("^([a-zA-Z][a-zA-Z0-9+-.]*):");

    static void assertWellFormed(String value, boolean restrictScheme) {
        assertTrue(!value.startsWith(","), "leading comma: " + value);
        assertTrue(!value.endsWith(","), "trailing comma: " + value);
        assertTrue(!value.contains(",,"), "double comma: " + value);
        // normalized output separates candidates with ", "; a URL-internal comma is never followed by a space
        String[] cands = value.split(", ", -1);
        for (String raw : cands) {
            String c = raw.trim();
            assertTrue(!c.isEmpty(), "empty candidate in: " + value);
            String[] parts = c.split("\\s+", -1);
            assertTrue(parts.length <= 2, "too many tokens: '" + c + "' in " + value);
            String url = parts[0];
            // any actual scheme must be http/https
            Matcher m = Scheme.matcher(url);
            if (restrictScheme && m.find()) {
                String s = m.group(1).toLowerCase();
                assertTrue(s.equals("http") || s.equals("https"), "bad scheme leak: '" + url + "' in " + value);
            }
            if (parts.length == 2) {
                String d = parts[1];
                char last = d.charAt(d.length() - 1);
                assertTrue(last == 'w' || last == 'x', "bad descriptor suffix: '" + d + "' in " + value);
                String num = d.substring(0, d.length() - 1);
                assertTrue(num.matches("\\d+(\\.\\d+)?") && !num.matches("0+(\\.0+)?"),
                    "bad descriptor number: '" + d + "' in " + value);
                if (last == 'w') assertTrue(!num.contains("."), "width must be integer: " + d);
            }
        }
    }

    @Test void fuzz() {
        String[] atoms = {"", ",", " ", "\t", "\n", "\f", "\r", "  ", ",,", "a.jpg", "https://ok.com/x",
            "http://ok.com/x", "1x", "2x", "100w", "0w", "0x", "1.5x", ".5x", "1.x", "-1x", "+1x",
            "javascript:alert(1)", "java%73cript:x", "data:,aaaa", "data:image/png;base64,AAAA",
            "\u0000", "\u0001", "\u007f", "//cdn.x/a", "/abs", "rel/x", "#", "?", "a,b", "a, b",
            "java&#x73;cript:1", "java&#x73cript:1", "x%3Ay.jpg",
            "HTTP://X/Y", "custom:thing", "   ", "1x 2x", "a.jpg 0w", "\t1x", "a.jpg\t1x",
            "vbscript:msgbox(1)", "%6a%73:1", "1javascript:x", "a%20b.jpg"};
        Object[][] cfgs = {
            {sl(), true}, {sl().preserveRelativeLinks(true), true},
            {slAny(), false}, {slAny().preserveRelativeLinks(true), false}};
        String[] bases = {"https://example.com/page/", "ftp://example.com/page/", "", "https://example.com",
            "http://example.com/a/b"};
        java.util.Random rnd = new java.util.Random(42);
        for (Object[] cfg : cfgs) {
            Safelist safelist = (Safelist) cfg[0];
            boolean restrictScheme = (Boolean) cfg[1];
            Cleaner cleaner = new Cleaner(safelist);
            for (String base : bases) {
                for (int i = 0; i < 30000; i++) {
                    StringBuilder sb = new StringBuilder();
                    int n = rnd.nextInt(6);
                    for (int j = 0; j < n; j++) sb.append(atoms[rnd.nextInt(atoms.length)]);
                    String val = sb.toString().replace("'", "");
                    Document doc = Jsoup.parse("<img srcset='" + val + "'>", base);
                    Document clean = cleaner.clean(doc);
                    assertNotNull(clean);
                    String html = clean.body().html();
                    if (html.contains("srcset=\"")) {
                        String v = html.substring(html.indexOf("srcset=\"") + 8);
                        v = v.substring(0, v.indexOf('"'));
                        assertWellFormed(v.contains("&amp;") ? v.replace("&amp;", "&") : v, restrictScheme);
                    }
                    Document again = cleaner.clean(clean);
                    assertEquals(html, again.body().html(), "not idempotent: '" + val + "' base=" + base);
                    Document third = cleaner.clean(again);
                    assertEquals(html, third.body().html(), "unstable 3x: '" + val + "' base=" + base);
                }
            }
        }
    }
}

